"""H32 S3a: 07_manuscript/refs.bib = entries of 01_lit/refs.bib (itself generated by 01_lit/make_bib.py from
refs_verified.csv) whose key has verify_rule_2026-11-22 == VERIFIED. Duplicate keys: the first entry is kept.
    uv run python 07_manuscript/make_refs.py
"""
import csv, pathlib, re
ROOT = pathlib.Path(__file__).resolve().parents[1]
ok = {r["key"] for r in csv.DictReader(open(ROOT / "01_lit/refs_verified.csv", encoding="utf-8"))
      if r["verify_rule_2026-11-22"].strip() == "VERIFIED"}
src = (ROOT / "01_lit/refs.bib").read_text()
entries = re.findall(r"(@\w+\{([^,]+),.*?\n\}\n)", src, re.S)
seen, out, dropped = set(), [], []
for body, key in entries:
    if key in seen or key not in ok:
        dropped.append(key); continue
    seen.add(key); out.append(body)
# S3c B4: protect case in titles (plainnat lower-cases them); only braces are added, no text changes.
PROTECT = ["WildPPG", "PhysioNet", "PhysioBridge", "ArrythML", "TinyML", "WESAD", "Mondrian", "Shewhart", "Galaxy Watch",
           "Computing in Cardiology", "Catch22", "ICU", "ECG", "PPG", "HRV", "AI", "PID", "BGP", "CUSUM", "Phase II", "Phase I"]
PAT = re.compile(r"(?<![{\w])(" + "|".join(re.escape(w) for w in PROTECT) + r")(?![\w}])")


def protect(entry):
    return re.sub(r"(\n  title = \{)(.*?)(\},\n)", lambda m: m.group(1) + PAT.sub(r"{\1}", m.group(2)) + m.group(3), entry, count=1)


# S3c B4: Jui 2026 is an IEEE early-access article (Crossref page "1-1"); state that instead of "pages 1--1".
FIX_PAGES = {"Jui2026": ("  pages = {1--1}", "  note = {Early access}")}
out2 = []
for body in out:
    key = re.match(r"@\w+\{([^,]+),", body).group(1)
    if key in FIX_PAGES:
        a, b = FIX_PAGES[key]; assert a in body, key; body = body.replace(a, b)
    pb = protect(body)
    title = lambda e: re.search(r"\n  title = \{(.*?)\},\n", e).group(1)
    assert title(pb).replace("{", "").replace("}", "") == title(body), key   # PI 23-11: letters unchanged, braces only
    out2.append(pb)
out = out2
hdr = "% Generated by 07_manuscript/make_refs.py from 01_lit/refs.bib (VERIFIED rows of refs_verified.csv only). Do not edit.\n\n"
(ROOT / "07_manuscript/refs.bib").write_text(hdr + "\n".join(out))
print(len(out), "entries; dropped (duplicate or not VERIFIED):", dropped)
